-- DADOS FICTÍCIOS de demonstração da BIOMAQ (venda, fabricação, estoque, financeiro).
-- NÃO é migration de schema — é carga de dados pra apresentação. Rode UMA vez no SQL Editor.
-- Tudo é marcado (leads.origem='demo_seed', clientes.observacao_risco='DEMO-SEED',
-- servicos.descricao 'DEMO-SEED…', lancamentos/estoque_movimentacoes.nf_numero='DEMO') e
-- pode ser apagado de uma vez com 20260921110100_DEMO_biomaq_limpar_dados_ficticios.sql.
-- Pressupõe que 20260921100000_biomaq_config_empresa_catalogo.sql já foi aplicada.
-- Todos os nomes, CNPJs e valores são inventados.

DO $demo$
DECLARE
  v_emp uuid := 'dc3c3320-f652-4289-ae91-eab23ef956f2';
  v_users uuid[];
  v_u uuid;
  v_lead bigint;
  v_prod bigint;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM empresas WHERE id = v_emp) THEN RAISE EXCEPTION 'Empresa Biomaq não encontrada.'; END IF;
