  v_users := ARRAY(SELECT id FROM profiles WHERE empresa_id = v_emp ORDER BY (cargo = 'diretor') DESC, id);
  IF array_length(v_users, 1) IS NULL THEN RAISE EXCEPTION 'Biomaq não tem nenhum usuário em profiles.'; END IF;

